cd /app/repo; python3 - <<'E'
import csv,collections
from decimal import Decimal
from datetime import datetime,timezone
rows=list(csv.DictReader(open('/app/reports/issue-412/ledger.csv')))
print(collections.Counter(r['currency'] for r in rows))
def amt(s):
    s=s.replace(',','');n=s.startswith('(') or s.startswith('-');return -Decimal(s.strip('()-')) if n else Decimal(s)
def utc(w):
    d=datetime.fromisoformat(w)
    if d.tzinfo is None:d=d.replace(tzinfo=timezone.utc)
    return d.astimezone(timezone.utc)
for name,f in [('written',lambda w:w[:7]),('utc',lambda w:utc(w).strftime('%Y-%m'))]:
    t=collections.Counter()
    for r in rows:
        if f(r['when'])=='2026-03':t[r['account']]+=amt(r['amount'])
    print(name,t['FACILITIES'],t['OPS-EAST'])
# what about Z
E

