cd /app/repo; python3 - <<'E'
import csv,collections
from decimal import Decimal
from datetime import datetime,timezone
rows=list(csv.DictReader(open('/app/reports/issue-412/ledger.csv')))
def amt(s):
    s=s.replace(',','');n=s.startswith('(') or s.startswith('-');return -Decimal(s.strip('()-')) if n else Decimal(s)
def utc(w):
    d=datetime.fromisoformat(w)
    if d.tzinfo is None:d=d.replace(tzinfo=timezone.utc)
    return d.astimezone(timezone.utc)
t=collections.defaultdict(Decimal)
for r in rows:
    if r['account']!='FACILITIES':continue
    w=r['when'];a=w[:7];b=utc(w).strftime('%Y-%m')
    if a!=b and '2026-03' in (a,b) or '2026-03' in(a,b) and a!=b: t[(a,b,w[10:11]+w[19:] if len(w)>10 else '')]+=amt(r['amount'])
for k,v in sorted(t.items()):print(k,v)
